import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int totalPoints = Integer.parseInt(reader.readLine());
        if (totalPoints >= 100) {
            writer.print(0);
        } else {
            int[][] coords = new int[totalPoints + 1][5];
            for (int index = 1; index <= totalPoints; index++) {
                StringTokenizer st = new StringTokenizer(reader.readLine());
                for (int dim = 0; dim < 5; dim++) {
                    coords[index][dim] = Integer.parseInt(st.nextToken());
                }
            }
            Set<Integer> invalidIndices = new HashSet<>();
            for (int i = 1; i <= totalPoints; i++) {
                for (int j = 1; j <= totalPoints; j++) {
                    for (int k = 1; k <= totalPoints; k++) {
                        if (i == j || j == k || k == i) continue;
                        long[] vecA = new long[5], vecB = new long[5];
                        for (int d = 0; d < 5; d++) {
                            vecA[d] = coords[j][d] - coords[i][d];
                            vecB[d] = coords[k][d] - coords[i][d];
                        }
                        double dotProduct = 0;
                        long lengthA = 0, lengthB = 0;
                        for (int d = 0; d < 5; d++) {
                            dotProduct += vecA[d] * vecB[d];
                            lengthA += vecA[d] * vecA[d];
                            lengthB += vecB[d] * vecB[d];
                        }
                        double cosine = dotProduct / (Math.sqrt(lengthA) * Math.sqrt(lengthB));
                        if (Math.toDegrees(Math.acos(cosine)) + 1e-9 < 90) {
                            invalidIndices.add(i);
                        }
                    }
                }
            }
            writer.println(totalPoints - invalidIndices.size());
            for (int i = 1; i <= totalPoints; i++) {
                if (!invalidIndices.contains(i)) {
                    writer.println(i);
                }
            }
        }
        writer.close();
    }
}
